1655.     /**
1656.      * Return true when the next turn must hydrate state from the session store.
1657.      * This supports abrupt worker loss and direct worker-side dehydration.
1658.      */
1659.     async needsHydration(sessionId: string, options?: { trace?: SessionTraceWriter }): Promise<boolean> {
1660.         const trace = options?.trace;
1661.         if (!this.sessionStore) {
1662.             emitSessionManagerTrace(sessionId, "needsHydration=false session store disabled", { trace });
1663.             return false;
1664.         }
1665.         if (this.sessions.has(sessionId)) {
1666.             emitSessionManagerTrace(sessionId, "needsHydration=false session is still warm in memory", { trace });
1667.             return false;
1668.         }
1669. 
1670.         const sessionDir = path.join(this.sessionStateDir, sessionId);
1671.         if (fs.existsSync(sessionDir)) {
1672.             emitSessionManagerTrace(sessionId, "needsHydration=false local session directory already exists", { trace });
1673.             return false;
1674.         }
1675. 
