1693.     async destroySession(sessionId: string, options?: { lockHeld?: boolean }): Promise<void> {
1694.         if (!options?.lockHeld) {
1695.             return this._withSessionLock(sessionId, "destroySession", () => this.destroySession(sessionId, { lockHeld: true }));
1696.         }
1697.         const session = this.sessions.get(sessionId);
