1709.     async invalidateWarmSession(sessionId: string, options?: { lockHeld?: boolean }): Promise<void> {
1710.         if (!options?.lockHeld) {
1711.             return this._withSessionLock(sessionId, "invalidateWarmSession", () => this.invalidateWarmSession(sessionId, { lockHeld: true }));
1712.         }
1713.         const session = this.sessions.get(sessionId);
1714.         if (!session) return;
